import React, { useEffect, useRef, useState } from 'react';

const fullLines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"',
];

const sections = ['About', 'Projects', 'Contact'];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState('');
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);
  const [activeSection, setActiveSection] = useState('About');

  const refs = useRef({});

  // Typing Effect
  useEffect(() => {
    if (lineIndex < fullLines.length) {
      if (charIndex < fullLines[lineIndex].length) {
        const timeout = setTimeout(() => {
          setCurrentLine(prev => prev + fullLines[lineIndex][charIndex]);
          setCharIndex(i => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines(prev => [...prev, fullLines[lineIndex]]);
          setCurrentLine('');
          setCharIndex(0);
          setLineIndex(i => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine('');
        setCharIndex(0);
        setLineIndex(0);
        setLoop(l => l + 1);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  // Sidebar Scroll Detection
  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.6 }
    );

    sections.forEach(section => {
      const ref = refs.current[section.toLowerCase()];
      if (ref) observer.observe(ref);
    });

    return () => observer.disconnect();
  }, []);

  const highlightLine = (line, isTyping = false) => {
    const [left, right] = line.split('=');
    const variable = left?.trim();
    const value = right?.trim();

    return (
      <div
        className={`whitespace-pre w-fit ${
          isTyping ? 'border-r-2 border-gray-400 animate-blink' : ''
        }`}
      >
        <span className="text-[#9CDCFE]">{variable}</span>
        <span className="text-[#d4d4d4]"> = </span>
        {value?.startsWith('"') ? (
          <span className="text-[#ce9178]">{value}</span>
        ) : (
          <span className="text-[#b5cea8]">{value}</span>
        )}
      </div>
    );
  };

  return (
    <div className="flex min-h-screen bg-[#1e1e1e] text-[#d4d4d4] font-mono text-base">
      {/* VSCode-style Sidebar */}
      <div className="w-24 bg-[#252526] text-center py-4 flex flex-col items-center space-y-4 fixed top-0 left-0 h-screen z-50">

        {sections.map(sec => (
          <div
            key={sec}
            className={`text-sm writing-vertical transition-all duration-200 tracking-wide ${
              activeSection === sec ? 'text-white font-bold' : 'text-gray-400'
            }`}
            style={{ writingMode: 'vertical-rl', transform: 'rotate(270deg)' }}
          >
            {sec}
          </div>
        ))}

      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 space-y-32 overflow-y-auto scroll-smooth">
        <section
          id="About"
          ref={el => (refs.current['about'] = el)}
          className="min-h-screen"
        >
          <h1 className="text-2xl mb-6">About</h1>
          <div className="space-y-2 text-left">
            {typedLines.map((line, idx) => (
              <div key={`done-${loop}-${idx}`}>{highlightLine(line)}</div>
            ))}
            {lineIndex < fullLines.length && (
              <div>{highlightLine(currentLine, true)}</div>
            )}
          </div>
        </section>

        <section
          id="Projects"
          ref={el => (refs.current['projects'] = el)}
          className="min-h-screen"
        >
          <h1 className="text-2xl mb-4">Projects</h1>
          <p>🚧 Projects go here...</p>
        </section>

        <section
          id="Contact"
          ref={el => (refs.current['contact'] = el)}
          className="min-h-screen"
        >
          <h1 className="text-2xl mb-4">Contact</h1>
          <p>📬 Contact details go here...</p>
        </section>
      </div>
    </div>
  );
}
